(9123,3,1,'Let me browse your goods.',0,3,128,0,0,0,0,'',0),
(9203,0,0,'The Festival Loremaster asked me to speak with you.',0,1,1,9282,0,0,0,'',0),
(9278,0,0,'The Festival Talespinner asked me to speak with you.',0,1,1,9281,0,0,0,'',0),
(9981,0,9,'I would like to go to the battleground.',0,12,1048576,0,0,0,0,'',0),
(10311,0,1,'I want to browse your goods.',0,3,128,0,0,0,0,'',0),
(10434,0,2,'I need a ride.',0,4,8192,0,0,0,0,'',0),
(10862,0,0,'Kalec sent me...',0,1,1,10863,0,0,0,'',0),
(10863,0,0,'No no no, you don\'t understand. I\'m here to help.',0,1,1,10864,0,0,0,'',0),
(10864,0,0,'Met someone? I didn\'t know there were any other dragons out here.',0,1,1,10865,0,0,0,'',0),
(10865,0,0,'...the spirit healer?\n',0,1,1,10866,0,0,0,'',0),
(10866,0,0,'I\'m sorry, I didn\'t mean to be rude, I just...',0,1,1,10867,0,0,0,'',0),
(10867,0,0,'That\'s not what I was saying at all.',0,1,1,10868,0,0,0,'',0),
(10868,0,0,'I\'m the... forget it. I\'m here to warn you that the black dragonflight is here hunting you.',0,1,1,10869,0,0,0,'',0),
(10869,0,0,'You already know? Why don\'t you go stop them then?',0,1,1,10870,0,0,0,'',0),
(10870,0,0,'But Kalecgos is already out there trying to stop them. He needs your help.',0,1,1,10871,0,0,0,'',0),
(10871,0,0,'You\'ll come then?',0,1,1,10872,0,0,0,'',0),
(10872,0,0,'I\'m going to let him know right away. Meet us at Sable Ridge.',0,1,1,10873,0,0,0,'',0),
(11573,0,1,'I want to browse your goods.',0,3,128,0,0,0,0,'',0),
(11969,8,0,'The wind rider master',0,1,1,1902,1902,0,0,'',0),
(11969,9,0,'Guild Master & Vendor',0,1,1,1903,1903,0,0,'',0),
