(11969,11,0,'Officer\'s Lounge',0,1,1,7046,0,0,0,'',0),
(11969,12,0,'Portals',0,1,1,12245,12245,0,0,'',0),
(11969,13,0,'A profession trainer',0,1,1,1942,0,0,0,'',0),
(11969,14,0,'The stable master',0,1,1,4902,4902,0,0,'',0),
(11969,15,0,'Zeppelin Master',0,1,1,9727,0,0,0,'',0),
(12835,5,1,'I want to browse your goods.',0,3,128,0,0,0,0,'',0),
(13348,0,0,'Can you charge my Cryptomancer\'s Decoder Ring?',0,1,1,57800,0,0,0,'',0),
(14988,0,0,'I\'m ready to go, General.',0,1,1,0,0,0,0,'',0),
(50002,0,0,'My apologies, I did not realize that you could understand what I was saying. What is it you are doing out here?',0,1,1,50003,0,0,0,'',0),
(50003,0,0,'Do you? Perhaps you should tell me what it is that is bothering you.',0,1,1,50004,0,0,0,'',0),
(50004,0,0,'What deal?',0,1,1,50005,0,0,0,'',0),
(50005,0,0,'So how did he break the deal?',0,1,1,50007,0,0,0,'',0),
(50010,0,0,'It is good to see the Burning Blade is taking over where the Shadow Council once failed.',0,1,1,50011,0,0,0,'',0),
(50011,0,0,'So the Searing Blade is expendable?',0,1,1,50012,0,0,0,'',0),
(50012,0,0,'If there is anything you would have of me...',0,1,1,50013,0,0,0,'',0),
